function precioFinal(base, descuento = 10) {
  return base - descuento;
}

precioFinal(100);            // 90
precioFinal(100, 0);         // 100
precioFinal(100, undefined); // 90

function total(precio, impuesto = 0) {
  return precio + impuesto;
}

const resultado = total(10, 2);
console.log(resultado); // 12

