function buscarUsuario(usuarios, id) {
  const usuario = usuarios.find((item) => item.id === id);

  if (usuario === undefined) {
    return null;
  }

  return usuario;
}

function limpiar(texto) {
  return texto.trim();
}

function unirNombre(nombre, apellido) {
  return `${limpiar(nombre)} ${limpiar(apellido)}`;
}
